-- from information_schema.columns
-- where table_schema='public' and table_name='report_areas' and column_name='report_number';
--   -> want is_identity=YES, identity_generation=BY DEFAULT, is_nullable=NO
--
-- select count(*), count(report_number), min(report_number), max(report_number)
-- from report_areas;
--   -> want count = count(report_number), i.e. no NULLs left
